def fallback(xyz):
    # Isotropic orthographic projection of the saved xyz, not a deformed illustration.
    points = [(x, y) for x, y, _ in xyz]
    cx = sum(p[0] for p in points) / 9
    cy = sum(p[1] for p in points) / 9
    scale = 74
    p = [(260 + (x-cx)*scale, 235 - (y-cy)*scale) for x,y in points]
    bits = ['<svg viewBox="0 0 520 460" role="img" aria-label="Nine atoms of malonaldehyde on the saved central PBE image" class="molecule-fallback"><title>Saved molecular geometry; O-H dashed segments are distance guides</title>']
    for a,b in [(0,2),(2,3),(2,4),(4,5),(4,6),(6,7),(6,8),(0,1),(1,7)]:
        dash = ' stroke-dasharray="4 6"' if 1 in (a,b) else ''
        bits.append(f'<line x1="{p[a][0]}" y1="{p[a][1]}" x2="{p[b][0]}" y2="{p[b][1]}" stroke="var(--muted)" stroke-width="4"{dash}/>')
    for i,(x,y) in enumerate(p):
        color = 'var(--oxygen)' if i in (0,7) else 'var(--teal)' if i == 1 else 'var(--carbon)' if i in (2,4,6) else 'var(--hydrogen)'
        radius = 17 if i in (0,2,4,6,7) else 12
        bits.append(f'<circle cx="{x}" cy="{y}" r="{radius}" fill="{color}" stroke="var(--panel)" stroke-width="2"/>')
    return ''.join(bits) + '</svg>'


def render(d, article, literature):
    metrics = d['metrics']
    def source(title, definition, keys, caveat):
        links = ' · '.join(f'<a href="{d["evidence"][k]["url"]}">{esc(k.replace("_"," "))}</a>' for k in keys)
        return f'''<details class="evidence"><summary>Read the evidence <span aria-hidden="true">↗</span></summary><div class="evidence-body"><dl><dt>Claim</dt><dd>{title}</dd><dt>Definition</dt><dd>{definition}</dd><dt>Primary sources</dt><dd>{links}</dd><dt>Reconstruct</dt><dd><a href="{REPO}/blob/main/tools/build_research_site.py">Deterministic data builder</a> · <a href="{REPO}/blob/main/tools/verify_train119_diagnostic.py">Saved-data verifier</a></dd><dt>Boundary</dt><dd>{caveat}</dd></dl></div></details>'''
    def head(number, kicker, title, text):
        return f'<div class="page-head"><p class="eyebrow">{number} / {kicker}</p><h1>{title}</h1><p class="lede">{text}</p></div>'
    def table(caption, columns, rows):
        return '<div class="table-wrap" tabindex="0" role="region" aria-label="'+esc(caption)+'"><table><caption>'+caption+'</caption><thead><tr>'+''.join('<th scope="col">'+c+'</th>' for c in columns)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
    def stage(id, cls=''):
        return f'<div id="{id}" class="molecular-stage {cls}" role="img" aria-label="Interactive saved molecular geometry. Use the adjacent controls to explore.">{fallback(d["molecule"][4]["xyz"])}</div>'
    def stat(label, value, unit='', id=''):
        ident = f' id="{id}"' if id else ''
        return f'<div class="stat"><span>{label}</span><strong{ident}>{value}</strong><small>{unit}</small></div>'
    nav = ''.join(f'<a href="#{k}" data-route="{k}">{n}</a>' for k,n in zip(SECTIONS,NAMES))
    pages = []
    hero = f'''<section id="overview" data-page class="page active"><div class="hero"><div class="hero-copy"><p class="eyebrow">A computational chemistry case study</p><h1>One proton.<br><em>Several tests<br> of trust.</em></h1><p class="lede">A small molecule. Two ways to place the training data. And a much harder question: when should we trust a machine-learned potential?</p><p class="byline">Mikhail Fofonov <span>·</span> Proton / Potential</p><div class="actions"><a class="button primary" href="#molecule">Explore the molecule <span>↗</span></a><a class="button quiet" href="#story">Play the research story <span>▷</span></a></div><p class="fineprint">An explorable account of saved calculations.<br>No live molecular simulation. No invented physics.</p></div><div class="hero-exhibit"><div class="exhibit-label"><span>C₃H₄O₂ / MALONALDEHYDE</span><span id="hero-frame">PBE IMAGE 05 / 09</span></div>{stage('hero-molecule')}<div class="exhibit-readout"><span>O1—O8 <strong id="hero-roo">{d['molecule'][4]['roo']:.3f}</strong> Å</span><span>q<sub>PT</sub> <strong id="hero-q">{d['molecule'][4]['q']:.3f}</strong> Å</span><span class="tiny-label">THE CARBON FRAME MOVES TOO</span></div><div class="motion-bar js-control"><button id="hero-play" class="play-button" aria-label="Play the molecular introduction">▷ Play</button><label class="sr-only" for="hero-slider">Introduction path position</label><input id="hero-slider" type="range" min="0" max="8" step="0.002" value="4"><button id="hero-reset" class="icon-button" aria-label="Reset molecular introduction">↺</button></div><p class="stage-caption">Nine computed images; smooth in-between motion is display interpolation. Drag horizontally to rotate.</p></div></div><div class="spine"><div class="spine-intro"><p class="eyebrow">The result, without the shortcuts</p><h2>Keep these tests separate.</h2></div><div class="spine-items"><a href="#sampling"><span class="micro">THE ORIGINAL DESIGN</span><strong>60 / 60</strong><p>The same label count.<br>Different spatial placement.</p></a><a href="#seeds"><span class="micro">REPEATED TRAINING</span><strong>3 of 5</strong><p>Paired seeds favor Targeted<br>on both primary metrics.</p></a><a href="#train119"><span class="micro">LATER LOCAL DIAGNOSIS</span><strong>11 frames</strong><p>Small PBE-relative force errors.<br>Not independent validation.</p></a></div></div><div class="editorial-note"><p>A convincing fit is a beginning.<br><em>It is not the final verdict.</em></p><a href="#longread">Read the full research essay →</a></div></section>'''
    pages.append(hero)
    rows = [[m['image'], f"{m['q']:.6f}", f"{m['roo']:.6f}", f"{d['profiles']['PBE'][i]:.6f}"] for i,m in enumerate(d['molecule'])]
    pages.append(f'''<section id="molecule" data-page class="page">{head('01','The geometry','The proton does not move alone.','Follow one saved minimum-energy path. As H2* changes sides, the oxygen atoms approach one another and the carbon skeleton rearranges.')}<div class="path-layout"><div class="panel stage-panel"><div class="panel-heading"><span class="micro">SAVED PBE PATH</span><span id="path-state" class="badge">Image 5 / 9</span></div>{stage('path-molecule')}<div class="image-strip js-control" aria-label="Nine saved PBE images">{''.join(f'<button data-image="{i}" aria-label="Select saved PBE image {i+1}">{i+1:02d}</button>' for i in range(9))}</div><div class="motion-bar js-control"><button id="path-play" class="play-button">▷ Play path</button><label class="sr-only" for="path-slider">Path position</label><input id="path-slider" type="range" min="0" max="8" step="0.002" value="4"><button id="path-reset" class="icon-button" aria-label="Reset path and view">↺</button></div><div class="control-row js-control"><label class="check-label"><input id="path-snap" type="checkbox"> Saved images only</label><button id="path-front" class="text-button">Front view</button><button id="path-studio" class="text-button">Studio view</button></div><p class="stage-caption">Solid rods show schematic connectivity; dashed segments are O–H distance guides, not bond orders. Atom radii are illustrative.</p></div><aside><div class="measurement-grid">{stat('O1–H2*',f"{d['molecule'][4]['left']:.4f}",'Å','path-left')}{stat('H2*–O8',f"{d['molecule'][4]['right']:.4f}",'Å','path-right')}{stat('O1–O8',f"{d['molecule'][4]['roo']:.4f}",'Å','path-roo')}{stat('Relative PBE energy',f"{d['profiles']['PBE'][4]:.3f}",'meV','path-energy')}</div><div class="chart-panel"><h2>A geometry, not a clock.</h2><div id="path-chart" class="chart compact" role="img" aria-label="PBE relative energy along the nine saved images"></div><p class="formula">q<sub>PT</sub> = r(O1–H2*) − r(O8–H2*)</p><p class="small">O–O contracts by <strong>{d['contraction_percent']:.2f}%</strong> from the left endpoint to the central image. This is a geometric observation, not a measured rate effect.</p></div></aside></div>{source('The molecular frame changes along the saved path.','Distances are evaluated directly from the same nine Cartesian geometries. Energy lines join saved values; they are not new model evaluations.',['path','methods'],'A NEB path is not a real-time trajectory or a demonstrated tunneling path. All 21 internal degrees of freedom are not captured by qPT alone.')}<details class="data-table"><summary>Inspect the nine original numerical supports</summary>{table('Saved PBE path; energy relative to the lower endpoint',['Image','qPT / Å','O–O / Å','PBE / meV'],rows)}</details></section>''')
    samprows = [[branch, p['id'], 'shared' if p['shared'] else 'added', f"{p['q']:.6f}",f"{p['roo']:.6f}"] for branch in ('basin','targeted') for p in d['sampling'][branch]]
    pages.append(f'''<section id="sampling" data-page class="page">{head('02','The data budget','Same budget. Different questions.','Both original models saw 36 shared configurations. The other 24 labels were placed near the minima or toward the proton-transfer region.')}<div class="controls section-controls js-control"><button id="sampling-play" class="play-button">▷ Reveal the experiment</button><button id="sampling-reset" class="text-button">Show all points</button><span id="sampling-count" class="live-note">36 shared + 24 added per model</span></div><div class="twin-panels"><div class="chart-panel"><div class="panel-heading"><h2>Basin60</h2><span class="model-tag basin">NEAR THE MINIMA</span></div><div id="sampling-basin" class="chart tall" role="img" aria-label="Actual qPT and O-O projection of Basin60 training configurations"></div></div><div class="chart-panel"><div class="panel-heading"><h2>Targeted60</h2><span class="model-tag targeted">TOWARD THE TRANSITION</span></div><div id="sampling-targeted" class="chart tall" role="img" aria-label="Actual qPT and O-O projection of Targeted60 training configurations"></div></div></div><div class="legend"><span><i class="legend-dot neutral"></i>Shared configurations</span><span><i class="legend-dot basin"></i>Basin additions</span><span><i class="legend-diamond targeted"></i>Targeted additions</span></div><div class="reading-pair"><div><p class="eyebrow">What the experiment varied</p><h2>Where to spend the labels.</h2><p>The plotted positions are real geometry descriptors, not decorative points. This two-coordinate projection makes placement visible without pretending to represent the full configuration space.</p></div><div class="scope-note"><strong>24 candidates. K = 24.</strong><p>The transition pool contained exactly 24 candidates, and all 24 were included. This experiment does not establish competitive MaxVol subset ranking within a larger pool. Equal label count also does not imply identical total wall-clock cost.</p></div></div>{source('Two equal-size training sets differ in spatial allocation.','Membership comes from candidate IDs; qPT and O–O are recomputed from CFG coordinates. Reveal order is presentation only.',['train_basin','train_targeted','methods'],'A projection is not a full PES. The reveal is not the training optimizer, a dynamics run, or a selection competition.')}<details class="data-table"><summary>Inspect all source configurations</summary>{table('Original training data projected into two coordinates',['Branch','Candidate ID','Role','qPT / Å','O–O / Å'],samprows)}</details></section>''')
    erows = [[i+1]+[f'{d["profiles"][name][i]:.6f}' for name in ('PBE','Basin60','Targeted60')] for i in range(9)]
    pages.append(f'''<section id="landscape" data-page class="page">{head('03','The original model pair','An impressive fit. A specific result.','On the fixed PBE path, the original transition-focused model is much closer to the reference. These are the preserved models, not a later best-seed selection.')}<div class="controls section-controls js-control"><button id="energy-play" class="play-button">▷ Reveal the profiles</button><label class="check-label"><input type="checkbox" checked data-model="Basin60"> Basin60</label><label class="check-label"><input type="checkbox" checked data-model="Targeted60"> Targeted60</label><label>Selected image <input id="energy-image" type="range" min="0" max="8" step="1" value="4"></label></div><div class="profile-layout"><div class="chart-panel"><div class="panel-heading"><h2>One reference path.</h2><div class="legend"><span><i class="legend-dot pbe"></i>PBE</span><span><i class="legend-dot basin"></i>Basin60</span><span><i class="legend-diamond targeted"></i>Targeted60</span></div></div><div id="energy-chart" class="chart tall" role="img" aria-label="Relative energies of PBE, Basin60, and Targeted60 on the nine PBE images"></div><div id="energy-readout" class="plot-readout">Selected image: 5</div></div><aside class="metric-comparison"><p class="eyebrow">LOWER IS BETTER</p><h2>The original errors</h2><div class="comparison-row"><span>Barrier / meV</span><strong class="basin-text">{metrics['Basin60']['barrier_error']:.3f}</strong><strong class="targeted-text">{metrics['Targeted60']['barrier_error']:.3f}</strong></div><div class="comparison-row"><span>Central force RMSE / eV/Å</span><strong class="basin-text">{metrics['Basin60']['force_rmse']:.5f}</strong><strong class="targeted-text">{metrics['Targeted60']['force_rmse']:.5f}</strong></div><p class="small">Basin60 · Targeted60<br>One frozen stochastic realization per branch.</p><div class="scope-note"><strong>A barrier is not an entire curve.</strong><p>Each series uses its own lower endpoint as zero. The residual panel shows the signed difference from the PBE relative profile.</p></div></aside></div><div class="chart-panel residual-panel"><h2>Look at the differences.</h2><div id="energy-residual" class="chart short" role="img" aria-label="Signed relative profile residuals of the original models versus PBE"></div></div>{source('The original Targeted60 reduces the two preserved primary errors.','Barrier = max(E1…E9) − min(E1,E9); error is its absolute difference from PBE. Central force RMSE combines the three images with |qPT| ≤ 0.15 Å.',['path','basin','targeted','randomness'],'Two path endpoints overlap common36. The result is artifact-specific and the five-seed follow-up is SEED_SENSITIVE.')}<details class="data-table"><summary>Read the exact relative energies</summary>{table('Original fixed-path profiles / meV',['Image','PBE','Basin60','Targeted60'],erows)}</details></section>''')
    seedrows = [[r['index']+1,r['seed'],r['model'],f"{r['barrier']:.6f}",f"{r['force']:.8f}"] for r in d['seeds']]
    pages.append(f'''<section id="seeds" data-page class="page">{head('04','Repeat the training','Five seeds. Five different comparisons.','A single fit cannot separate data placement from initialization. Keep every pair on the screen and follow what changes when the locked training procedure is repeated.')}<div class="controls section-controls js-control"><button id="seeds-play" class="play-button">▷ Reveal the five pairs</button><button id="seeds-all" class="text-button">Show all</button><label>Inspect pair <select id="seed-select"><option value="all">All five pairs</option>{''.join(f'<option value="{i}">Pair {i+1}</option>' for i in range(5))}</select></label></div><div class="twin-panels"><div class="chart-panel"><h2>Barrier error</h2><div id="seeds-barrier" class="chart tall" role="img" aria-label="Five paired barrier errors, all results retained"></div></div><div class="chart-panel"><h2>Central force error</h2><div id="seeds-force" class="chart tall" role="img" aria-label="Five paired central force errors, all results retained"></div></div></div><div class="legend"><span><i class="legend-dot basin"></i>Basin60</span><span><i class="legend-diamond targeted"></i>Targeted60</span><span>Smaller errors are to the left.</span></div><div class="result-banner"><strong>3 / 5</strong><p>Targeted is better on both primary metrics in three pairs.<br><span id="seed-description">One pair reverses both results; another has a mixed ordering.</span></p><span class="badge">SEED_SENSITIVE</span></div>{source('The ordering depends on the training seed in this five-pair audit.','All five paired 64-bit seed identities are retained as strings; no best-seed filtering or confidence bands are introduced.',['seeds','randomness'],'Three of five is a description of these five pairs, not a 60% success probability for arbitrary future fits. An evaluation-order repair preserved the original outputs.')}<details class="data-table"><summary>Exact seeds and all ten evaluations</summary>{table('Five paired seeds; not an inferred distribution',['Pair','64-bit seed','Branch','Barrier / meV','Force / eV/Å'],seedrows)}</details></section>''')
    localrows = [[r['replay_index'],r['role'],f"{r['gamma_saved']:.12f}",f"{r['force_component_RMSE_eV_A']:.8f}",'crossing' if r['above_stop'] else 'below stop'] for r in d['local']]
    frame_options = ''.join(f'<option value="{r["replay_index"]}">{r["replay_index"]} · {r["role"]}</option>' for r in d['local'])
    pages.append(f'''<section id="train119" data-page class="page">{head('05','A separate development study','Two verdicts. The same geometry.','A coverage warning and a direct force comparison answer different questions. Train119 makes that distinction visible without changing its historical failure.')}<div class="controls section-controls js-control"><label>Saved segment <select id="diagnostic-group"><option value="CROSSING7">Crossing7 · 142–148</option><option value="CHALLENGE4">Challenge4 · 93–96</option></select></label><button id="diagnostic-play" class="play-button">▷ Follow the frames</button><label>Frame <select id="diagnostic-frame">{frame_options}</select></label></div><div class="twin-panels"><div class="chart-panel"><span class="micro">COVERAGE DIAGNOSTIC · DIMENSIONLESS</span><h2>Did the saved grade cross the stop?</h2><div id="gamma-chart" class="chart tall" role="img" aria-label="Saved gamma minus the unchanged historical stop, multiplied by one thousand"></div><p class="small">Plot: (γ − stop) × 10³. Zero is the frozen stop, not zero grade. <br>stop = {d['stop']:.16f}</p></div><div class="chart-panel"><span class="micro">DIRECT PBE COMPARISON · eV/Å</span><h2>How large was the force error?</h2><div id="force-error-chart" class="chart tall" role="img" aria-label="Local per-configuration force-component RMSE and A2 threshold"></div><p class="small">A2 = 0.09 eV/Å, applied to the RMSE of all 27 components in each configuration. It is not a maximum-component bound.</p></div></div><div id="diagnostic-readout" class="result-banner compact-banner"></div><div class="reading-pair"><div><h2>A narrower, useful observation.</h2><p>All eleven selected local errors are below A2. Five saved coverage crossings remain. The points come from two different 100 K trajectory segments used in development, not a new Train119 trajectory.</p><a class="button" id="inspect-forces-link" href="#forces">Look inside this force error →</a></div><div class="scope-note"><strong>STATIC_APPLICABILITY_FAIL remains.</strong><p>The model was not promoted to Gate1. The stop was not relaxed. Neighboring frames, adaptive selection and reused benchmarks do not establish independent generalization.</p></div></div><details class="sub-study"><summary>Train119 on the reused PBE path: a small barrier error is not a uniform error bound</summary><div class="twin-panels"><div><div id="train119-profile" class="chart" role="img" aria-label="Separate Train119 and PBE development profiles"></div></div><div><div id="train119-residual" class="chart" role="img" aria-label="Separate Train119 relative profile residuals"></div></div></div><p>Barrier error: <strong>{metrics['Train119']['barrier_error']:.6f} meV</strong>. Maximum relative-profile error: <strong>{metrics['Train119']['profile_max_abs_error']:.6f} meV</strong>. Central force RMSE: <strong>{metrics['Train119']['force_rmse']:.6f} eV/Å</strong>. Both endpoint geometries overlap training under the established geometric screen. This is a 119-configuration adaptive model, not a third equal-budget branch.</p></details>{source('The saved coverage criterion fails while the selected local force errors stay below A2.','Gamma is read from the saved grading; force RMSE is recomputed from official QE force blocks and stored MTP outputs, with XML and geometry checks.',['train119','diagnostic','corrections','geometry'],'These are correlated development diagnostics. No universal gamma-to-error mapping, independent test, experimental accuracy or reactive MD is demonstrated.')}<details class="data-table"><summary>All eleven local comparisons</summary>{table('Two different saved 100 K segments',['Replay index','Set','Saved gamma','Force RMSE / eV/Å','Coverage'],localrows)}</details></section>''')
    pages.append(f'''<section id="forces" data-page class="page">{head('06','Behind the scalar','Twenty-seven numbers behind one score.','Rotate the molecule, select an atom, and compare the saved PBE and MTP forces. The arrows are forces—not predicted displacements or a new dynamics run.')}<div class="controls section-controls js-control"><label>Configuration <select id="force-frame">{frame_options}</select></label><button id="forces-play" class="play-button">▷ Reveal the vectors</button><button id="force-reset" class="text-button">Reset view</button></div><div class="force-layout"><div class="panel stage-panel"><div class="panel-heading"><span class="micro">CLICK AN ATOM OR USE THE BUTTONS</span><span class="badge" id="force-atom-badge">H2*</span></div>{stage('force-molecule')}<div class="atom-buttons js-control" aria-label="Choose an atom">{''.join(f'<button data-atom="{i}" aria-label="Select atom {name}" aria-pressed="{str(i==1).lower()}">{name}</button>' for i,name in enumerate(['O1','H2*','C3','H4','C5','H6','C7','O8','H9']))}</div><div class="controls vector-controls js-control"><label class="check-label"><input data-vector="pbe" type="checkbox" checked> PBE</label><label class="check-label"><input data-vector="mtp" type="checkbox" checked> MTP</label><label class="check-label"><input data-vector="error" type="checkbox" checked> Difference</label><label>Arrow scale <select id="force-scale"><option value="1">1×</option><option value="2" selected>2×</option><option value="4">4×</option></select></label></div><p class="stage-caption">At 1×, 1 eV/Å is drawn as one model-space Å. This is a display scale, not a displacement. Coordinates and arrows undergo the same rigid rotation.</p></div><aside class="force-details"><span class="eyebrow">SAVED LAB-FRAME COMPONENTS</span><h2 id="force-selection">H2* · Replay 145</h2><div id="force-components"></div><div class="measurement-grid">{stat('Selected atom |ΔF|','—','eV/Å','selected-error')}{stat('Whole-frame RMSE','—','eV/Å','selected-rmse')}</div><p class="formula">RMSE<sub>F</sub> = √[Σ<sub>a,k</sub>(ΔF<sub>ak</sub>)² / 27]</p><p class="small">The table uses the original laboratory x, y, z axes. It does not rotate its numbers with the camera. The vector difference is MTP − PBE.</p><div class="scope-note"><strong>H2* is not C3.</strong><p>The transferred proton is atom 2 in one-based indexing. The historical selector-component annotation concerned atom 3 / y. The two are kept separate here.</p></div><p id="force-source" class="chapter-source"></p></aside></div>{source('The scalar RMSE can be inspected through the original atomic force vectors.','Reference forces are parsed from the official QE block, cross-checked with XML, and compared to the matching stored MTP prediction. All 297 components come from primary public files.',['geometry_crossing7','prediction_crossing7','geometry_challenge4','prediction_challenge4','corrections'],'Arrows are not electron density, probabilities, displacements or a fresh model evaluation. A small selected-atom error is not a global accuracy claim.')}</section>''')
    pages.append(f'''<section id="story" data-page class="page">{head('07','A directed research sequence','From a good fit to a better question.','Six scenes connect the molecular path, training data and the limits of the conclusion. Pause at any point; then open the underlying experiment.')}<div class="cinema" id="story-cinema"><div class="cinema-top"><span>PROTON / POTENTIAL</span><span id="story-count">01 / 06</span></div><div class="cinema-content"><div class="cinema-copy"><span id="story-kicker" class="micro">A SAVED REACTION PATH</span><h2 id="story-title">One proton.<br>A moving scaffold.</h2><p id="story-caption">Nine saved PBE images. Display time is not reaction time.</p><a id="story-link" href="#molecule">Explore this scene →</a></div><div class="cinema-visual">{stage('story-molecule')}<div id="story-chart" class="chart tall" role="img" aria-label="Scientific data for the current directed scene"></div></div></div><div class="cinema-bottom"><span id="story-progress-label">GEOMETRY / DATA / ROBUSTNESS / COVERAGE</span><span>NO NEW PHYSICAL CALCULATIONS</span></div></div><div class="motion-bar story-controls js-control"><button id="story-play" class="play-button">▷ Play the story</button><label class="sr-only" for="story-slider">Research story progress</label><input id="story-slider" type="range" min="0" max="1" step="0.001" value="0"><button id="story-reset" class="icon-button" aria-label="Restart research story">↺</button></div><div class="story-chapters js-control">{''.join(f'<button data-chapter="{i}"><span>{i+1:02d}</span>{name}</button>' for i,name in enumerate(['Molecule','Placement','Original fit','Five seeds','Two verdicts','The boundary']))}</div><div id="film-area"></div><div class="reading-pair"><div><h2>Animation explains.<br>The evidence stays.</h2><p>All scenes can be stopped and inspected. Their final plots remain visible; an animation never replaces the complete numerical comparison.</p></div><div class="scope-note"><strong>The older films are archived.</strong><p>The original v1.2.0 silent films contain Russian on-screen captions. They are preserved in the historical release, not embedded in this English exhibit. <a href="{REPO}/releases/tag/v1.2.0">Historical media and provenance ↗</a></p></div></div></section>''')
